// FixedClipPlayer.swift — fixed clips (PRD §10.3, §23.5; CONTRACTS §2.2 play_fixed).
//
//  * manifest.json from the downloaded cache (Application Support/fixed/), else the bundle (`fixed/`, the
//    folder reference to ios/AhBo/Resources/fixed generated by ops)
//  * AVAudioPlayer with metering → face `level` at ~20 Hz (never sent for silent fake clips)
//  * face `say_start {id: say_id, text, segments}` in the SAME run-loop turn as `play()` succeeds;
//    `say_end {id}` at the end; then the caller replies `playback_done {clip_id, say_id, error?}`
//  * if the audio can't play, the face is still driven for the manifest duration and playback_done is sent
//    with `error` — playback never hangs
//  * one clip at a time: a more important (lower number) or equal priority clip interrupts; a less
//    important one waits

import AVFoundation
import Foundation

struct FixedManifest: Decodable, Sendable {
    struct Clip: Decodable, Sendable {
        let file: String
        let text: String
        let segments: [[Double]]
        let duration: Double
    }
    let version: String
    let clips: [String: Clip]
}

@MainActor
final class FixedClipPlayer {
    struct Request {
        let clipId: String?            // nil for voice notes played through the same queue
        let sayId: String
        let priority: Int
        let fileURL: URL?
        let faceStart: [String: Any]
        let fallbackDuration: Double
        let sendsLevel: Bool
        let done: (String?) -> Void    // error or nil
    }

    var face: (([String: Any]) -> Void)?
    /// true while any clip (or voice note) is playing — used for self-wake suppression (§20.4.5 rule 3).
    var onBusyChange: ((Bool) -> Void)?

    private(set) var manifest: FixedManifest?
    private var manifestDir: URL?
    private var current: (req: Request, player: AVAudioPlayer?, task: Task<Void, Never>?)?
    private var waiting: [Request] = []

    var cacheVersion: String { manifest?.version ?? "" }
    var isBusy: Bool { current != nil }

    static var cacheDir: URL {
        let base = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
        return base.appendingPathComponent("fixed", isDirectory: true)
    }

    init() { loadManifest() }

    /// Downloaded cache first, else the bundled copy.
    func loadManifest() {
        for dir in [Self.cacheDir, Bundle.main.url(forResource: "fixed", withExtension: nil)].compactMap({ $0 }) {
            let f = dir.appendingPathComponent("manifest.json")
            if let data = try? Data(contentsOf: f), let m = try? JSONDecoder().decode(FixedManifest.self, from: data) {
                manifest = m
                manifestDir = dir
                Log.info("fixed", "manifest \(m.version) (\(m.clips.count) clips) from \(dir == Self.cacheDir ? "cache" : "bundle")")
                return
            }
        }
        Log.error("fixed", "no fixed-clip manifest (cache or bundle)")
    }

    /// Download manifest + clips when the server's version differs (welcome / config.update).
    func refresh(to version: String, api: APIClient) async {
        guard !version.isEmpty, version != cacheVersion else { return }
        do {
            let data = try await api.get("/media/fixed/manifest.json")
            let m = try JSONDecoder().decode(FixedManifest.self, from: data)
            let fm = FileManager.default
            let staging = Self.cacheDir.deletingLastPathComponent().appendingPathComponent("fixed.staging", isDirectory: true)
            try? fm.removeItem(at: staging)
            try fm.createDirectory(at: staging, withIntermediateDirectories: true)
            for clip in Set(m.clips.values.map(\.file)) {
                let audio = try await api.get("/media/fixed/\(clip)")
                try audio.write(to: staging.appendingPathComponent(clip))
            }
            try data.write(to: staging.appendingPathComponent("manifest.json"))
            try? fm.removeItem(at: Self.cacheDir)
            try fm.moveItem(at: staging, to: Self.cacheDir)
            Log.info("fixed", "downloaded fixed clips \(m.version)")
            loadManifest()
        } catch {
            Log.error("fixed", "fixed-clip download failed: \(error.localizedDescription)")
        }
    }

    /// play_fixed. Returns false (and calls `done("unknown_clip")`) when the clip isn't in the manifest.
    @discardableResult
    func playFixed(clipId: String, sayId: String, priority: Int, done: @escaping (String?) -> Void) -> Bool {
        guard let clip = manifest?.clips[clipId], let dir = manifestDir else {
            Log.error("fixed", "clip \(clipId) not in manifest")
            done("unknown_clip")
            return false
        }
        let segments: [[Any]] = clip.segments.map { s in
            s.enumerated().map { i, v in i < 2 ? Int(v) as Any : v as Any }     // [firstChar, endChar, start, end]
        }
        let faceStart: [String: Any] = ["type": "say_start", "id": sayId, "text": clip.text, "segments": segments]
        enqueue(Request(clipId: clipId, sayId: sayId, priority: priority, fileURL: dir.appendingPathComponent(clip.file),
                        faceStart: faceStart, fallbackDuration: max(clip.duration, 0.5), sendsLevel: true, done: done))
        return true
    }

    func enqueue(_ r: Request) {
        if let cur = current {
            if r.priority > cur.req.priority { waiting.append(r); return }
            finish(error: "interrupted")
        }
        start(r)
    }

    /// stop_all: end everything now.
    func stopAll() {
        let q = waiting
        waiting.removeAll()
        if current != nil { finish(error: "stopped") }
        q.forEach { $0.done("stopped") }
    }

    private func start(_ r: Request) {
        var player: AVAudioPlayer?
        if let url = r.fileURL {
            player = try? AVAudioPlayer(contentsOf: url)
            player?.isMeteringEnabled = true
            player?.prepareToPlay()
        }
        let playing = player?.play() ?? false
        // Same run-loop turn as play(): the face's caption clock starts with the audio (§23.5).
        var faceStart = r.faceStart
        if faceStart["segments"] == nil, faceStart["durationSec"] == nil {
            faceStart["durationSec"] = playing ? (player?.duration ?? r.fallbackDuration) : r.fallbackDuration
        }
        face?(faceStart)
        onBusyChange?(true)
        let error: String? = playing ? nil : (r.fileURL == nil ? "no_file" : "play_failed")
        if let error { Log.error("fixed", "\(r.clipId ?? r.sayId): \(error); driving the face by duration") }
        let duration = playing ? (player?.duration ?? r.fallbackDuration) : r.fallbackDuration
        let task = Task { @MainActor [weak self] in
            await self?.monitor(player: playing ? player : nil, duration: duration, sendsLevel: r.sendsLevel)
            guard !Task.isCancelled else { return }
            self?.finish(error: error)
        }
        current = (r, player, task)
    }

    /// Mouth level at ~20 Hz until the clip ends (or its duration + 3 s watchdog passes).
    private func monitor(player: AVAudioPlayer?, duration: Double, sendsLevel: Bool) async {
        let t0 = Date()
        var heard = false
        while !Task.isCancelled {
            try? await Task.sleep(for: .milliseconds(50))
            let elapsed = Date().timeIntervalSince(t0)
            if let p = player {
                if !p.isPlaying || elapsed > duration + 3 { return }
                if sendsLevel {
                    p.updateMeters()
                    let db = p.averagePower(forChannel: 0)
                    let v = max(0, min(1, (Double(db) + 45) / 45))
                    if v > 0.02 { heard = true }
                    if heard { face?(["type": "level", "v": (v * 100).rounded() / 100]) }
                }
            } else if elapsed >= duration {
                return
            }
        }
    }

    private func finish(error: String?) {
        guard let cur = current else { return }
        current = nil
        cur.task?.cancel()
        cur.player?.stop()
        face?(["type": "say_end", "id": cur.req.sayId])
        onBusyChange?(false)
        cur.req.done(error)
        if let next = waiting.enumerated().min(by: { $0.element.priority < $1.element.priority }) {
            waiting.remove(at: next.offset)
            start(next.element)
        }
    }
}
